let mqttConnection;

function ensureConnected() {
  if (!mqttConnection) {
    return bb.connect()
      .then(connection => {
        mqttConnection = connection;
        console.log("Connected to AWS IoT.");
        return connection;
      })
      .catch(error => {
        console.error('Connection error:', error);
        return null;
      });
  }
  return Promise.resolve(mqttConnection);
}

