function printTag(tagData) {
  //console.log("Printing tag:");
  if (tagData.ulid) {
    storeEvent(tagData.ulid, {
      action: 'printing',
      thingName: tagData.thingName,
      type: tagData.type
    });
  }
  return publishToMqtt(tagData);
}

process.on("SIGINT", function () {
  console.log("Terminating client...");
  if (mqttConnection) {
    bb.disconnect(mqttConnection).then(() => {
      redisClient.quit();
      process.exit();
    });
  } else {
    redisClient.quit();
    process.exit();
  }
});

